        ("cancelled", "new"),
        // ready ->
        ("ready", "on-hold"),
        // in-implementation ->
        ("in-implementation", "on-hold"),
    ]
    .into_iter()
    .map(|(f, t)| Transition {
        from: f.to_string(),
